html:
{% set is_tax = doc.invoice_type == "Tax Invoice" %}
<style>
  @page { size: A4; margin: 8mm; }
  body { margin: 0; padding: 0; font-family: Arial, sans-serif; color: #000; }
  .inv-page { width: 100%; min-height: auto; box-sizing: border-box; font-family: Arial, sans-serif; color: #000; font-size: 12px; }
  .inv-title { text-align: center; font-size: 19px; font-weight: 700; line-height: 1; margin: 0 0 3px 0; text-transform: uppercase; }
  .inv-main { width: 100%; border-collapse: collapse; table-layout: fixed; border: 1px solid #000; }
  .inv-main td { border: 1px solid #000; vertical-align: top; }
  .company-block { padding: 6px 7px 4px 7px; }
  .company-logo-row { margin-bottom: 4px; }
  .company-logo-row img { width: 85px; height: 72px; object-fit: contain; display: block; }
  .company-name { font-size: 14px; font-weight: 700; line-height: 1.15; margin-bottom: 4px; text-transform: uppercase; }
  .company-line { font-size: 12px; line-height: 1.25; }
  .doc-info { width: 100%; border-collapse: collapse; table-layout: fixed; }
  .doc-info td { border-left: none; border-right: none; border-top: none; border-bottom: 1px solid #000; padding: 3px 5px; height: 26px; font-size: 12px; line-height: 1.15; }
  .doc-info tr:last-child td { border-bottom: none; }
  .info-value { font-weight: 700; }
  .party-cell { padding: 5px 6px; }
  .party-title { font-size: 12px; margin-bottom: 4px; }
  .party-name { font-size: 14px; font-weight: 700; line-height: 1.25; }
  .party-text { font-size: 12px; line-height: 1.35; }
  .goods-table { width: 100%; border-collapse: collapse; table-layout: fixed; margin-top: -1px; }
  .goods-table th, .goods-table td { border: 1px solid #000; padding: 4px 5px; font-size: 11px; line-height: 1.25; }
  .goods-table th { text-align: center; font-weight: 400; }
  .center { text-align: center; }
  .right { text-align: right; }
  .bold { font-weight: 700; }
  .sub-product { display: block; margin-top: 3px; font-style: italic; font-size: 11px; font-weight: 400; }
  .footer-table { width: 100%; border-collapse: collapse; table-layout: fixed; border-left: 1px solid #000; border-right: 1px solid #000; border-bottom: 1px solid #000; }
  .footer-table td { border: 1px solid #000; padding: 6px 8px; vertical-align: top; font-size: 12px; }
  .totals-line { display: flex; justify-content: space-between; padding: 2px 0; }
  .totals-line.grand { font-weight: 700; font-size: 13px; border-top: 1px solid #000; margin-top: 3px; padding-top: 4px; }
  .bottom-table { width: 100%; border-collapse: collapse; table-layout: fixed; border-left: 1px solid #000; border-right: 1px solid #000; border-bottom: 1px solid #000; }
  .bottom-table td { border: 1px solid #000; padding: 6px 6px; height: 40px; vertical-align: top; font-size: 12px; }
  .sign-cell { text-align: right; }
  .sign-company { font-size: 12px; font-weight: 700; margin-bottom: 25px; }
  .sign-title { font-size: 11px; }
  .generated { text-align: center; font-size: 12px; margin-top: 8px; }
  .stamp-area { margin-top: -55px; margin-left: 60%; width: 90px; height: 90px; }
  .stamp-area img { width: 90px; height: 90px; object-fit: contain; opacity: 0.9; }
  @media print { .inv-page { page-break-after: avoid; } }
</style>

<div class="inv-page">

  <div class="inv-title">{{ doc.invoice_type or "Tax Invoice" }}</div>

  <table class="inv-main">
    <tr>
      <td style="width:45%;" class="company-block">
        <div class="company-logo-row"><img src="/files/AP_Logo.webp" alt="Company Logo" width="85" height="72" onerror="this.style.display='none'"></div>
        <div class="company-name">Asia Petrochemicals LLC OPC</div>
        <div class="company-line">Plot # A 23 B, Al Jazeera Industrial Area</div>
        {% if is_tax %}<div class="company-line">TRN : {{ frappe.db.get_value("Company", frappe.db.get_default("company"), "tax_id") or "100283348900003" }}</div>{% endif %}
        <div class="company-line">Emirate : Ras al-Khaimah</div>
        <div class="company-line">E-Mail : info@asia-petrochem.com</div>
      </td>

      <td style="width:27.5%;">
        <table class="doc-info">
          <tr><td><div>Invoice No.</div><div class="info-value">{{ doc.name }}</div></td></tr>
          <tr><td><div>Delivery Note</div><div class="info-value">{{ doc.delivery_note_ref or "-" }}</div></td></tr>
          <tr><td><div>Supplier's Ref.</div><div class="info-value">{{ doc.supplier_ref or "-" }}{% if doc.supplier_ref_date %} dt. {{ frappe.utils.formatdate(doc.supplier_ref_date) }}{% endif %}</div></td></tr>
          <tr><td><div>Buyer's Order No.</div><div class="info-value">{{ doc.buyers_order_no or "-" }}</div></td></tr>
          <tr><td><div>Despatch Document No.</div><div class="info-value">{{ doc.despatch_document_no or "-" }}</div></td></tr>
          <tr><td><div>Despatched through</div><div class="info-value">{{ doc.despatched_through or "-" }}</div></td></tr>
          <tr><td><div>Vessel/Flight No.</div><div class="info-value">{{ doc.vessel_flight_no or "-" }}</div></td></tr>
          <tr><td><div>City/Port of Loading</div><div class="info-value">{{ doc.port_of_loading or "-" }}</div></td></tr>
        </table>
      </td>

      <td style="width:27.5%;">
        <table class="doc-info">
          <tr><td><div>Dated</div><div class="info-value">{{ frappe.utils.formatdate(doc.invoice_date) }}</div></td></tr>
          <tr><td><div>Mode/Terms of Payment</div><div class="info-value">{{ doc.mode_of_payment or "-" }}</div></td></tr>
          <tr><td><div>Other Reference(s)</div><div class="info-value">{{ doc.other_reference or "-" }}</div></td></tr>
          <tr><td><div>Dated</div><div class="info-value">{{ frappe.utils.formatdate(doc.buyers_order_date) if doc.buyers_order_date else "-" }}</div></td></tr>
          <tr><td><div>Delivery Note Date</div><div class="info-value">{{ frappe.utils.formatdate(doc.delivery_note_date) if doc.delivery_note_date else "-" }}</div></td></tr>
          <tr><td><div>Place of receipt by shipper</div><div class="info-value">{{ doc.place_of_receipt or "-" }}</div></td></tr>
          <tr><td><div>City/Port of Discharge</div><div class="info-value">{{ doc.port_of_discharge or "-" }}</div></td></tr>
        </table>
      </td>
    </tr>

    <tr>
      <td class="party-cell">
        <div class="party-title">Consignee</div>
        <div class="party-name">{{ doc.consignee_name or "-" }}</div>
        <div class="party-text">{{ doc.consignee_address or "" }}</div>
        {% if doc.consignee_phone or doc.consignee_fax %}
          <div class="party-text">
            {% if doc.consignee_phone %}PH: {{ doc.consignee_phone }}{% endif %}
            {% if doc.consignee_fax %}&nbsp;&nbsp;FAX: {{ doc.consignee_fax }}{% endif %}
          </div>
        {% endif %}
      </td>
      <td colspan="2" class="party-cell">
        <div class="party-title">Buyer</div>
        <div class="party-name">{{ doc.buyer_name or "-" }}</div>
        <div class="party-text">{{ doc.buyer_address or "" }}</div>
        {% if doc.buyer_phone or doc.buyer_fax %}
          <div class="party-text">
            {% if doc.buyer_phone %}PH: {{ doc.buyer_phone }}{% endif %}
            {% if doc.buyer_fax %}&nbsp;&nbsp;FAX: {{ doc.buyer_fax }}{% endif %}
          </div>
        {% endif %}
        <div class="party-text">
          {% if doc.buyer_emirate %}Emirate&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: {{ doc.buyer_emirate }}<br>{% endif %}
          {% if doc.buyer_country %}Country&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: {{ doc.buyer_country }}<br>{% endif %}
          {% if doc.place_of_supply %}Place of supply&nbsp;: {{ doc.place_of_supply }}{% endif %}
        </div>
      </td>
    </tr>
    <tr>
      <td colspan="3" style="padding:5px 7px;"><div>Terms of Delivery</div><div class="info-value">{{ doc.terms_of_delivery or "-" }}</div></td>
    </tr>
  </table>

  <table class="goods-table">
    <thead>
      <tr>
        <th style="width:{% if is_tax %}4%{% else %}4%{% endif %};">Marks & Nos./<br>Container No.</th>
        <th style="width:{% if is_tax %}4%{% else %}4%{% endif %};">No. & Kind<br>of Pkgs.</th>
        <th style="width:{% if is_tax %}25%{% else %}45%{% endif %};">Description of Goods</th>
        <th style="width:{% if is_tax %}8%{% else %}10%{% endif %};">Quantity</th>
        <th style="width:{% if is_tax %}7%{% else %}10%{% endif %};">Rate</th>
        <th style="width:{% if is_tax %}5%{% else %}8%{% endif %};">per</th>
        {% if is_tax %}<th style="width:5%;">VAT<br>%</th>{% endif %}
        <th style="width:{% if is_tax %}10%{% else %}19%{% endif %};">Amount</th>
        {% if is_tax %}
        <th style="width:11%;">Taxable<br>Value(AED)</th>
        <th style="width:8%;">VAT<br>(AED)</th>
        <th style="width:13%;">Total<br>Incl.VAT(AED)</th>
        {% endif %}
      </tr>
    </thead>
    <tbody>
      {% for row in (doc.items or []) %}
      <tr>
        <td class="center">{{ row.marks_and_nos or "-" }}</td>
        <td class="center">{{ row.packages or "-" }}</td>
        <td>
          {{ (row.description or row.item_name or row.item or "-").split("\n")[0] }}
          {% if "\n" in (row.description or "") %}<span class="sub-product">{{ row.description.split("\n")[1] }}</span>{% endif %}
        </td>
        <td class="center">{{ row.quantity }} {{ row.uom or "" }}</td>
        <td class="right">{{ "%.2f"|format(row.rate or 0) }}</td>
        <td class="center">{{ row.uom or "" }}</td>
        {% if is_tax %}<td class="center">{{ row.vat_percentage }} %</td>{% endif %}
        <td class="right">{{ "%.2f"|format(row.amount or 0) }}</td>
        {% if is_tax %}
        <td class="right">{{ "%.2f"|format(row.taxable_value or 0) }}</td>
        <td class="right">{{ "%.2f"|format(row.vat_amount or 0) }}</td>
        <td class="right">{{ "%.2f"|format(row.total_incl_vat or 0) }}</td>
        {% endif %}
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <table class="footer-table">
    <tr>
      <td style="width:55%;">
        <div>Amount Chargeable (in words)</div>
        <div class="bold">{{ doc.amount_in_words or "-" }}</div>
        {% if is_tax %}
        <br>
        <div>VAT Amount (in words)</div>
        <div class="bold">{{ doc.vat_amount_in_words or "-" }}</div>
        {% endif %}
      </td>
      <td style="width:45%;">
        <div class="totals-line"><span>Taxable Value</span><span>{{ "%.2f"|format(doc.taxable_value or 0) }}</span></div>
        {% if is_tax %}<div class="totals-line"><span>Value Added Tax {{ doc.vat_percentage or 5 }} %</span><span>{{ "%.2f"|format(doc.vat_amount or 0) }}</span></div>{% endif %}
        <div class="totals-line grand"><span>Invoice Total</span><span>{{ "%.2f"|format(doc.grand_total or 0) }}</span></div>
        <div class="right" style="margin-top:4px;">E. &amp; O.E</div>
      </td>
    </tr>
  </table>

  <table class="bottom-table">
    <tr>
      <td style="width:55%;">
        <div>Declaration</div>
        <div>We declare that this invoice shows the actual price of the goods described and that all particulars are true and correct.</div>
      </td>
      <td style="width:45%;" class="sign-cell">
        <div class="sign-company">for Asia Petrochemicals LLC OPC</div>
        <div class="sign-title">Authorised Signatory</div>
      </td>
    </tr>
  </table>

  <div class="generated">This is a Computer Generated Invoice</div>

</div>
